def comps(m):
    seen=set(); n=0
    for i in range(4):
        for j in range(4):
            if m[i][j] and (i,j) not in seen:
                n+=1; st=[(i,j)]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b))
                    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<4 and 0<=y<4 and m[x][y] and (x,y) not in seen: st.append((x,y))
    return n
